  types = {
    ["aeroway=aerodrome"] = {cell = 38, group = "transport", look = "stand", uk = "Аеродром", en = "Airfield", textUk = "Поле зі злітною смугою. Смугу кладуть уздовж панівних вітрів: літаки злітають і сідають проти вітру, бо так розгін і пробіг коротші.", textEn = "A field with a runway. The runway lies along the prevailing winds: aircraft take off and land into the wind, which shortens both runs."},
    ["aeroway=airstrip"] = {cell = 38, group = "transport", look = "stand", uk = "Злітна смуга", en = "Airstrip", textUk = "Поле зі злітною смугою. Смугу кладуть уздовж панівних вітрів: літаки злітають і сідають проти вітру, бо так розгін і пробіг коротші.", textEn = "A field with a runway. The runway lies along the prevailing winds: aircraft take off and land into the wind, which shortens both runs."},
