    ["amenity=library"] = {cell = 4, group = "civic", look = "plaque", uk = "Бібліотека", en = "Library", textUk = "Зібрання книжок, відкрите для всіх. Книжки на полицях стоять за шифром, тому серед сотень тисяч томів потрібний знаходять за хвилину.", textEn = "A collection of books open to everyone. The books stand by shelf mark, so one volume among hundreds of thousands is found in a minute."},
    ["amenity=nightclub"] = {cell = 49, group = "civic", look = "blade", uk = "Нічний клуб", en = "Nightclub"},
    ["amenity=school"] = {cell = 9, group = "civic", look = "plaque", uk = "Школа", en = "School"},
    ["amenity=theatre"] = {cell = 30, group = "civic", look = "plaque", uk = "Театр", en = "Theatre", textUk = "Будівля для вистав. Сцена театру набагато більша, ніж видно із зали: над нею й обабіч ховаються декорації всіх дій.", textEn = "A building for plays. Its stage is far larger than the hall can see: the sets of every act hide above it and to its sides."},
    ["amenity=university"] = {cell = 9, group = "civic", look = "plaque", uk = "Університет", en = "University", textUk = "Вища школа, де водночас навчають і досліджують.", textEn = "A school of higher learning that both teaches and does research."},
    ["artwork_type=bust"] = {cell = 8, group = "sight", look = "stand", uk = "Погруддя", en = "Bust", textUk = "Скульптурний портрет: голова й плечі на постаменті. Форма прийшла з античного Риму, де так зберігали портрети предків.", textEn = "A sculpted portrait: head and shoulders on a pedestal. The form comes from ancient Rome, where portraits of ancestors were kept this way."},
    ["artwork_type=installation"] = {cell = 45, group = "sight", look = "stand", uk = "Інсталяція", en = "Installation", textUk = "Мистецький об'єкт, зібраний із різних речей і матеріалів для конкретного місця.", textEn = "An artwork put together of various things and materials for one particular place."},
    ["artwork_type=mural"] = {cell = 19, group = "sight", look = "plaque", uk = "Мурал", en = "Mural", textUk = "Розпис на всю стіну будинку. Глуха торцева стіна багатоповерхівки — найбільше полотно, яке може дістатися художникові.", textEn = "A painting over the whole wall of a building. The blank end wall of a tower block is the largest canvas an artist can get."},
    ["artwork_type=sculpture"] = {cell = 45, group = "sight", look = "stand", uk = "Скульптура", en = "Sculpture", textUk = "Об'ємний твір, який можна обійти довкола: з кожного боку він виглядає інакше.", textEn = "A work in three dimensions that can be walked around: it looks different from every side."},
    ["artwork_type=statue"] = {cell = 50, group = "sight", look = "stand", uk = "Статуя", en = "Statue", textUk = "Скульптура людини на повен зріст. Бронзову статую відливають порожньою, зі стінками завтовшки в палець, інакше вона важила б у кілька разів більше.", textEn = "A full-length sculpture of a person. A bronze statue is cast hollow, its walls a finger thick; solid, it would weigh several times as much."},
    ["cat:atm"] = {cell = 25, group = "money", look = "", uk = "Банкомат", en = "ATM"},
