    ["cat:sight"] = {cell = 49, group = "sight", look = "plaque", uk = "Пам'ятка", en = "Sight", textUk = "Місце, яке варто побачити.", textEn = "A place worth seeing."},
    ["cat:station_map"] = {cell = 7, group = "transport", look = "", uk = "Зупинка", en = "Stop"},
    ["cat:toilets"] = {cell = 25, group = "car", look = "", uk = "Туалет", en = "Toilets"},
    ["cat:water_vending"] = {cell = 47, group = "water", look = "", uk = "Автомат з водою", en = "Water machine"},
    ["cat:well"] = {cell = 47, group = "water", look = "", uk = "Криниця", en = "Well", textUk = "Шахта, викопана до водоносного шару. Глибина криниці показує, як глибоко тут лежить ґрунтова вода: у долині це кілька метрів, на пагорбі — десятки.", textEn = "A shaft dug down to the water table. Its depth tells how deep the groundwater lies here: a few metres in a valley, tens of metres on a hill."},
    ["healthcare=laboratory"] = {cell = 40, group = "health", look = "blade", uk = "Лабораторія", en = "Laboratory"},
    ["highway=bus_stop"] = {cell = 7, group = "transport", look = "", uk = "Автобусна зупинка", en = "Bus stop"},
    ["historic=aircraft"] = {cell = 38, group = "sight", look = "stand", uk = "Літак на постаменті", en = "Aircraft memorial", textUk = "Справжній літак, піднятий на постамент — зазвичай біля аеродрому чи льотного училища.", textEn = "A real aircraft raised on a pedestal, usually by an airfield or a flying school."},
    ["historic=archaeological_site"] = {cell = 15, group = "sight", look = "stand", bare = true, uk = "Археологічна пам'ятка", en = "Archaeological site", textUk = "Місце, де в землі збереглися сліди давнього життя: вали городища, кургани, фундаменти. Більшість знахідок лежить неглибоко, тому такі місця охороняє закон.", textEn = "A place where the ground keeps traces of ancient life: the banks of a hillfort, burial mounds, foundations. Most finds lie shallow, so such places are protected by law."},
    ["historic=building"] = {cell = 29, group = "sight", look = "plaque", uk = "Історична будівля", en = "Historic building", textUk = "Будівля, цінна своїм віком, архітектурою чи подіями, які в ній відбулися.", textEn = "A building valued for its age, its architecture or what happened in it."},
    ["historic=castle"] = {cell = 11, group = "sight", look = "stand", bare = true, uk = "Замок", en = "Castle", textUk = "Укріплене житло володаря: мури, вежі й брама захищали і господаря, і округу. Замки ставили там, де сама місцевість допомагала оборонятися, — на скелі, пагорбі чи в закруті річки.", textEn = "The fortified home of a lord: its walls, towers and gate guarded both him and the land around. Castles were built where the ground itself helped the defence: on a rock, a hill or in a river bend."},
    ["historic=city_gate"] = {cell = 20, group = "sight", look = "stand", bare = true, uk = "Міська брама", en = "City gate", textUk = "В'їзд у місто крізь оборонний мур. На ніч браму зачиняли, а вдень біля неї брали мито з возів; нерідко брама — усе, що лишилося від міських мурів.", textEn = "The way into a town through its wall. It was shut for the night, and by day tolls were taken from the carts; often the gate is all that is left of the town walls."},
    ["historic=fort"] = {cell = 11, group = "sight", look = "stand", bare = true, uk = "Фортеця", en = "Fort", textUk = "Військове укріплення без палацу всередині. Низькі товсті вали й кутасті бастіони з'явилися разом з гарматами: високий мур ядро пробивало, а земляний вал — ні.", textEn = "A military stronghold with no palace inside. Low thick ramparts and angled bastions came with the cannon: a ball broke a high wall but not a bank of earth."},
    ["historic=locomotive"] = {cell = 28, group = "sight", look = "stand", uk = "Паровоз-пам'ятник", en = "Locomotive memorial", textUk = "Паровоз, що відпрацював своє і став пам'ятником біля станції чи депо.", textEn = "A steam engine that has done its work and stands as a monument by a station or a depot."},
    ["historic=manor"] = {cell = 29, group = "sight", look = "stand", uk = "Садиба", en = "Manor", textUk = "Панський будинок із парком, службами й господарським двором. Садиба була центром маєтку: звідси керували землями й селами довкола.", textEn = "A landowner's house with its park, outbuildings and farmyard. The manor was the heart of an estate: the lands and villages around were run from here."},
    ["historic=memorial"] = {cell = 31, group = "sight", look = "stand", uk = "Меморіал", en = "Memorial", textUk = "Знак пам'яті про людей чи подію. На відміну від великого пам'ятника, меморіал може бути скромним: камінь, дошка, хрест або стела з іменами.", textEn = "A mark of remembrance of people or an event. Unlike a great monument, a memorial may be modest: a stone, a plaque, a cross or a slab of names."},
    ["historic=monument"] = {cell = 33, group = "sight", look = "stand", uk = "Пам'ятник", en = "Monument", textUk = "Споруда на честь людини чи події, зведена так, щоб її було видно здалеку. Постамент піднімає фігуру над вулицею й відділяє її від буденного.", textEn = "A structure raised to honour a person or an event, built to be seen from afar. The pedestal lifts the figure above the street and sets it apart from the everyday."},
    ["historic=ruins"] = {cell = 42, group = "sight", look = "stand", bare = true, uk = "Руїни", en = "Ruins", textUk = "Залишки споруди, яку більше не відбудовували. За товщиною мурів, кладкою й обрисами фундаментів історики відновлюють, якою будівля була і коли її звели.", textEn = "What is left of a building nobody rebuilt. From the thickness of the walls, the masonry and the lines of the foundations, historians work out what it was and when it was built."},
    ["historic=tank"] = {cell = 51, group = "sight", look = "stand", uk = "Танк на постаменті", en = "Tank memorial", textUk = "Справжня бойова машина, поставлена на постамент як пам'ятник. Найчастіше це танк, який першим увійшов у місто.", textEn = "A real fighting vehicle set on a pedestal as a monument, most often the tank that was first to enter the town."},
    ["historic=wayside_cross"] = {cell = 14, group = "sight", look = "", uk = "Придорожній хрест", en = "Wayside cross", textUk = "Хрест при дорозі, на роздоріжжі чи на краю села. Їх ставили як оберіг громади, на подяку або на згадку; подорожні звірялися з ними, як з дороговказами.", textEn = "A cross by a road, at a fork or at the edge of a village. They were raised to guard the community, in thanks or in memory, and travellers took their bearings from them."},
    ["historic=wayside_shrine"] = {cell = 46, group = "sight", look = "", uk = "Капличка", en = "Wayside shrine", textUk = "Мала споруда з образом чи фігурою святого при дорозі. Не храм: у ній не служать, біля неї зупиняються на хвилину.", textEn = "A small structure by a road with the image or figure of a saint. Not a church: no service is held in it, people stop by it for a minute."},
    ["information=guidepost"] = {cell = 25, group = "sight", look = "", uk = "Вказівник", en = "Guidepost"},
    ["information=office"] = {cell = 25, group = "sight", look = "blade", uk = "Туристичний центр", en = "Tourist office"},
    ["leisure=fitness_centre"] = {cell = 1, group = "nature", look = "blade", uk = "Фітнес-центр", en = "Fitness centre"},
    ["leisure=garden"] = {cell = 18, group = "nature", look = "stand", uk = "Сад", en = "Garden", textUk = "Ділянка, де рослини вирощують заради краси, науки чи врожаю.", textEn = "Ground where plants are grown for beauty, study or harvest."},
    ["leisure=park"] = {cell = 55, group = "nature", look = "stand", uk = "Парк", en = "Park", textUk = "Зелена ділянка для відпочинку серед міста. Дерева парку помітно охолоджують повітря: влітку тут на кілька градусів прохолодніше, ніж на сусідній вулиці.", textEn = "Green ground for rest inside a town. Its trees cool the air noticeably: in summer it is a few degrees cooler here than in the next street."},
    ["leisure=pitch"] = {cell = 1, group = "nature", look = "", uk = "Спортивне поле", en = "Pitch"},
    ["leisure=playground"] = {cell = 1, group = "nature", look = "", uk = "Дитячий майданчик", en = "Playground"},
    ["leisure=sports_centre"] = {cell = 1, group = "nature", look = "plaque", uk = "Спортивний центр", en = "Sports centre"},
    ["leisure=stadium"] = {cell = 48, group = "nature", look = "stand", uk = "Стадіон", en = "Stadium", textUk = "Спортивна арена з трибунами довкола поля. Овальна форма не випадкова: так найбільше глядачів сидить на однаковій відстані від гри.", textEn = "A sports ground with stands around the field. The oval is no accident: it seats the most people at the same distance from the game."},
    ["leisure=swimming_pool"] = {cell = 59, group = "water", look = "plaque", uk = "Басейн", en = "Swimming pool"},
    ["man_made=cross"] = {cell = 14, group = "sight", look = "", uk = "Хрест", en = "Cross", textUk = "Хрест при дорозі, на роздоріжжі чи на краю села. Їх ставили як оберіг громади, на подяку або на згадку; подорожні звірялися з ними, як з дороговказами.", textEn = "A cross by a road, at a fork or at the edge of a village. They were raised to guard the community, in thanks or in memory, and travellers took their bearings from them."},
    ["man_made=lighthouse"] = {cell = 27, group = "sight", look = "stand", bare = true, uk = "Маяк", en = "Lighthouse", textUk = "Вежа зі світлом, що показує кораблям берег і небезпеку. Кожен маяк блимає у власному ритмі, тож уночі моряк упізнає його за самими спалахами.", textEn = "A tower with a light that shows ships the shore and its dangers. Every lighthouse flashes in a rhythm of its own, so at night a sailor knows it by the flashes alone."},
    ["man_made=obelisk"] = {cell = 33, group = "sight", look = "stand", uk = "Обеліск", en = "Obelisk", textUk = "Чотиригранний стовп, що звужується догори. Перші обеліски ставили єгиптяни перед храмами; відтоді це найпростіший спосіб позначити місце на віки.", textEn = "A four-sided pillar tapering to its top. The Egyptians raised the first before their temples; ever since it has been the plainest way to mark a place for centuries."},
    ["man_made=water_tower"] = {cell = 52, group = "sight", look = "stand", uk = "Водонапірна вежа", en = "Water tower", textUk = "Бак з водою, піднятий високо над землею. Вода з нього тече в труби власною вагою, тому тиск у мережі тримається навіть тоді, коли насоси стоять.", textEn = "A tank of water raised high above the ground. The water runs into the mains by its own weight, so the pressure holds even while the pumps stand still."},
    ["man_made=windmill"] = {cell = 61, group = "sight", look = "stand", bare = true, uk = "Вітряк", en = "Windmill", textUk = "Млин, жорна якого крутить вітер. Щоб ловити його з будь-якого боку, корпус або самий дах повертали довгим дишлом назустріч вітру.", textEn = "A mill whose stones are turned by the wind. To catch it from any side, the whole body or just the cap was turned into the wind by a long tail pole."},
    ["memorial=aircraft"] = {cell = 38, group = "sight", look = "stand", uk = "Літак на постаменті", en = "Aircraft memorial", textUk = "Справжній літак, піднятий на постамент — зазвичай біля аеродрому чи льотного училища.", textEn = "A real aircraft raised on a pedestal, usually by an airfield or a flying school."},
    ["memorial=bust"] = {cell = 8, group = "sight", look = "stand", uk = "Погруддя", en = "Bust", textUk = "Скульптурний портрет: голова й плечі на постаменті. Форма прийшла з античного Риму, де так зберігали портрети предків.", textEn = "A sculpted portrait: head and shoulders on a pedestal. The form comes from ancient Rome, where portraits of ancestors were kept this way."},
    ["memorial=cross"] = {cell = 14, group = "sight", look = "stand", uk = "Пам'ятний хрест", en = "Memorial cross", textUk = "Хрест на згадку про людей чи подію.", textEn = "A cross in memory of people or an event."},
    ["memorial=locomotive"] = {cell = 28, group = "sight", look = "stand", uk = "Паровоз-пам'ятник", en = "Locomotive memorial", textUk = "Паровоз, що відпрацював своє і став пам'ятником біля станції чи депо.", textEn = "A steam engine that has done its work and stands as a monument by a station or a depot."},
    ["memorial=obelisk"] = {cell = 33, group = "sight", look = "stand", uk = "Обеліск", en = "Obelisk", textUk = "Чотиригранний стовп, що звужується догори. Перші обеліски ставили єгиптяни перед храмами; відтоді це найпростіший спосіб позначити місце на віки.", textEn = "A four-sided pillar tapering to its top. The Egyptians raised the first before their temples; ever since it has been the plainest way to mark a place for centuries."},
    ["memorial=plaque"] = {cell = 39, group = "sight", look = "plaque", uk = "Меморіальна дошка", en = "Memorial plaque", textUk = "Дошка на стіні будинку, де жила чи працювала відома людина або сталася важлива подія.", textEn = "A plaque on the wall of a house where a notable person lived or worked, or where something important happened."},
    ["memorial=statue"] = {cell = 50, group = "sight", look = "stand", uk = "Статуя", en = "Statue", textUk = "Скульптура людини на повен зріст. Бронзову статую відливають порожньою, зі стінками завтовшки в палець, інакше вона важила б у кілька разів більше.", textEn = "A full-length sculpture of a person. A bronze statue is cast hollow, its walls a finger thick; solid, it would weigh several times as much."},
    ["memorial=stele"] = {cell = 33, group = "sight", look = "stand", uk = "Стела", en = "Stele", textUk = "Вертикальна плита з написом чи рельєфом.", textEn = "An upright slab with an inscription or a relief."},
    ["memorial=stone"] = {cell = 31, group = "sight", look = "stand", uk = "Пам'ятний камінь", en = "Memorial stone", textUk = "Камінь із написом на місці події або майбутнього пам'ятника.", textEn = "An inscribed stone at the place of an event, or where a monument is to stand."},
    ["memorial=tank"] = {cell = 51, group = "sight", look = "stand", uk = "Танк на постаменті", en = "Tank memorial", textUk = "Справжня бойова машина, поставлена на постамент як пам'ятник. Найчастіше це танк, який першим увійшов у місто.", textEn = "A real fighting vehicle set on a pedestal as a monument, most often the tank that was first to enter the town."},
    ["memorial=war_memorial"] = {cell = 31, group = "sight", look = "stand", uk = "Воєнний меморіал", en = "War memorial", textUk = "Пам'ять про загиблих на війні. Такі меморіали стоять майже в кожному селі й місті: на плитах — імена місцевих жителів, які не повернулися.", textEn = "In memory of those killed in war. Nearly every village and town has one: its slabs carry the names of the local people who did not come back."},
    ["mountain_pass=yes"] = {cell = 35, group = "nature", look = "stand", uk = "Перевал", en = "Mountain pass", textUk = "Найнижче місце гірського хребта, де його найлегше перетнути. Дороги через гори майже завжди шукають саме перевал, тож тут здавна стояли застави, корчми й митниці.", textEn = "The lowest place on a ridge, where it is easiest to cross. Roads over mountains nearly always look for a pass, so guard posts, inns and customs houses have stood at them for centuries."},
    ["natural=cave_entrance"] = {cell = 12, group = "nature", look = "stand", bare = true, uk = "Печера", en = "Cave", textUk = "Порожнина в скелі, найчастіше вимита водою у вапняку чи гіпсі. У глибині печери цілий рік тримається майже та сама температура — середня річна для цієї місцевості.", textEn = "A hollow in the rock, most often dissolved by water in limestone or gypsum. Deep inside, the temperature stays nearly the same all year: the yearly mean of the place."},
    ["natural=peak"] = {cell = 37, group = "nature", look = "", uk = "Вершина", en = "Peak", textUk = "Найвища точка гори або пагорба. Висоту рахують від рівня моря, а не від підніжжя, тому скромний на вигляд горб на плато може бути вищим за стрімку скелю біля берега.", textEn = "The highest point of a mountain or hill. Its height is counted from sea level, not from its foot, so a modest hump on a plateau can stand higher than a steep crag by the shore."},
    ["natural=rock"] = {cell = 41, group = "nature", look = "stand", uk = "Скеля", en = "Rock", textUk = "Вихід корінної породи на поверхню. Скелі лишаються там, де м'якші шари довкола вже зруйнували вода, мороз і вітер.", textEn = "Bedrock standing out of the ground. A rock remains where water, frost and wind have already worn the softer layers around it away."},
    ["natural=saddle"] = {cell = 35, group = "nature", look = "stand", uk = "Сідловина", en = "Saddle", textUk = "Пониження між двома вершинами одного хребта. З одного боку від сідловини рельєф підіймається до вершин, з іншого спадає в долини.", textEn = "A dip between two summits of one ridge. Along the ridge the ground rises to the summits; across it, it falls away into the valleys."},
    ["natural=spring"] = {cell = 47, group = "water", look = "stand", uk = "Джерело", en = "Spring", textUk = "Місце, де підземна вода сама виходить на поверхню. Вода джерела пройшла крізь шари піску й каменю, тому зазвичай холодна й чиста; з таких джерел починаються струмки й річки.", textEn = "A place where groundwater comes to the surface by itself. It has passed through layers of sand and rock, so it is usually cold and clear; streams and rivers begin at springs like this."},
    ["natural=stone"] = {cell = 41, group = "nature", look = "stand", uk = "Брила", en = "Boulder", textUk = "Окремий великий камінь. Чимало таких брил принесли льодовики: камінь може лежати за сотні кілометрів від скель, від яких відколовся.", textEn = "A single large stone. Many were carried by glaciers: a boulder may lie hundreds of kilometres from the rock it broke off."},
    ["natural=volcano"] = {cell = 57, group = "nature", look = "", uk = "Вулкан", en = "Volcano", textUk = "Гора, складена з того, що колись вилилося або вилетіло з надр: лави, попелу, уламків. Згаслий вулкан упізнають за конусом і кратером на вершині.", textEn = "A mountain built of what once poured or was thrown out of the earth: lava, ash and rock. An extinct one is known by its cone and the crater at the top."},
    ["railway=halt"] = {cell = 54, group = "transport", look = "", uk = "Зупинний пункт", en = "Railway halt"},
    ["railway=station"] = {cell = 54, group = "transport", look = "", uk = "Залізнична станція", en = "Railway station", textUk = "Місце, де зупиняються поїзди. Ширина колії на більшості залізниць Європи — 1435 мм, в Україні й далі на схід — 1520 мм, тому на кордоні вагонам міняють візки.", textEn = "Where trains stop. Most European railways run on a 1435 mm gauge, Ukraine and the lands to its east on 1520 mm, so carriages get new bogies at the border."},
    ["railway=subway_entrance"] = {cell = 32, group = "transport", look = "", uk = "Вхід у метро", en = "Metro entrance"},
    ["railway=tram_stop"] = {cell = 54, group = "transport", look = "", uk = "Трамвайна зупинка", en = "Tram stop"},
