    ["tourism=aquarium"] = {cell = 17, group = "sight", look = "plaque", uk = "Акваріум", en = "Aquarium", textUk = "Зібрання водних тварин і рослин за склом.", textEn = "A collection of water animals and plants behind glass."},
    ["tourism=artwork"] = {cell = 45, group = "sight", look = "stand", uk = "Мистецький об'єкт", en = "Artwork", textUk = "Твір мистецтва просто неба: скульптура, інсталяція чи розпис.", textEn = "A work of art in the open: a sculpture, an installation or a painting."},
    ["tourism=attraction"] = {cell = 49, group = "sight", look = "stand", uk = "Цікаве місце", en = "Attraction", textUk = "Місце, заради якого сюди приїздять.", textEn = "A place people come here to see."},
    ["tourism=gallery"] = {cell = 19, group = "sight", look = "plaque", uk = "Галерея", en = "Gallery", textUk = "Простір для виставок мистецтва. На відміну від музею, виставки тут змінюються, а роботи часто можна купити.", textEn = "A space for art exhibitions. Unlike a museum, its shows change, and the works can often be bought."},
    ["tourism=information"] = {cell = 25, group = "sight", look = "stand", bare = true, uk = "Інформація", en = "Information", textUk = "Стенд, мапа чи вказівник для подорожніх.", textEn = "A board, a map or a guidepost for travellers."},
    ["tourism=museum"] = {cell = 34, group = "sight", look = "plaque", uk = "Музей", en = "Museum", textUk = "Місце, де речі зберігають, досліджують і показують. У залах зазвичай виставлено лише малу частку зібрання: решта лежить у сховищах.", textEn = "A place where things are kept, studied and shown. The halls usually display only a small share of the collection; the rest lies in the stores."},
    ["tourism=theme_park"] = {cell = 60, group = "sight", look = "stand", uk = "Парк розваг", en = "Theme park", textUk = "Парк з атракціонами. Оглядове колесо в ньому — найпростіший спосіб побачити місто згори.", textEn = "A park of rides. Its big wheel is the simplest way to see the town from above."},
    ["tourism=viewpoint"] = {cell = 56, group = "sight", look = "stand", bare = true, uk = "Оглядовий майданчик", en = "Viewpoint", textUk = "Місце, з якого відкривається далекий краєвид. За ясної погоди з висоти 100 метрів над рівниною обрій лежить приблизно за 36 кілометрів.", textEn = "A place with a far view. On a clear day, from 100 metres above a plain the horizon lies about 36 kilometres away."},
    ["tourism=zoo"] = {cell = 36, group = "sight", look = "stand", uk = "Зоопарк", en = "Zoo", textUk = "Парк, де тримають і показують тварин. Сучасні зоопарки ще й розводять рідкісні види, щоб повертати їх у природу.", textEn = "A park where animals are kept and shown. Modern zoos also breed rare species to return them to the wild."},
    ["waterway=waterfall"] = {cell = 58, group = "water", look = "stand", bare = true, uk = "Водоспад", en = "Waterfall", textUk = "Річка падає з уступу там, де тверда порода змінюється м'якшою: вода вимиває м'яку швидше. Через це водоспад повільно відступає вгору за течією, лишаючи по собі ущелину.", textEn = "A river drops off a ledge where hard rock gives way to softer rock, which the water wears away faster. So a waterfall slowly retreats upstream and leaves a gorge behind it."},
  }}
